import {backofficeApiPath,hasBackofficePermission} from './admin-paths.js';
/* Installation dossiers contain safe metadata only. Runtime credentials and all
   provider operations belong to the authenticated server, never this module. */
const field=(name,label,help,example='',options={})=>({name,label,help,example,type:'text',required:true,...options});
const choice=(name,label,help,options,example=options[0]?.[0])=>field(name,label,help,example,{type:'select',options});
const step=(title,description,fields=[],extra={})=>({title,description,fields,...extra});
const scope=()=>choice('organizationReference','Klantorganisatie','Bron: geautoriseerde DG-organisatie. De naam bepaalt geen rechten.',[['fixture-org-studio','DG-TEST-001 · Voorbeeld Studio'],['fixture-org-dg','DG Webservices · fixture']]);
const project=()=>choice('projectRef','Project','Bron: toegankelijke projectcatalogus. Voorbeelden verlenen geen projecttoegang.',[['fixture-project-fieldgrid','Fieldgrid · fixture'],['fixture-project-dartflow','DartFlow · fixture']]);
const owner=()=>field('owner','Verantwoordelijke','Bron: eigen beheerafspraak; dit label kent geen toegangsrechten toe.','DG Applicaties');
const label=example=>field('configurationName','Configuratienaam','Een herkenbare interne naam, 3–80 tekens. Dit is geen provider-ID.',example,{maxLength:80});
const note=()=>field('operatorNote','Beheeropmerking','Optioneel. Alleen controlebevindingen; geen wachtwoorden, sleutels of berichtinhoud.','Proefrecord; eerst handmatig verifiëren.',{required:false,type:'textarea'});
const verify=(description='Controleer deze configuratierevisie op de server. In fixturemodus wordt alleen een begrensde simulatie vastgelegd.')=>step('Testen en bewijs',description,[],{check:true});
const review=(description='Bekijk omgeving, scope, wijzigingen en ontbrekend bewijs. Concept bewaren activeert niets en maakt geen externe bestelling.')=>step('Bekijken en bewaren',description,[],{review:true});

